namespace TheliaCMS\Twig;

use Thelia\Domain\Ai\Twig\AiTransparencyExtension;
use TheliaCMS\Generation\GeneratorSettings;
use Twig\Extension\AbstractExtension;
use Twig\TwigFunction;

/**
 * The sentence under a generated page, "Content generated by an AI (model) on
 * date.", when the site chose to show it: `{{ cms_ai_label(cms_page.provenance,
 * cms_page.locale) }}`. An empty string otherwise, so the theme prints it
 * without testing first.
 *
 * Off by default. The AI Act asks for a mark machines can read (article
 * 50(2)), which `ai_provenance_attributes()` prints whatever this setting; a
 * sentence for the reader is only asked of a text published to inform the
 * public that no person reviewed (article 50(4)).
 */
final class AiLabelExtension extends AbstractExtension
{
    public function __construct(
        private readonly GeneratorSettings $settings,
        private readonly AiTransparencyExtension $transparency,
    ) {
    }

    public function getFunctions(): array
    {
        return [
            new TwigFunction('cms_ai_label', $this->label(...)),
        ];
    }

    public function label(?string $provenance, ?string $locale = null): string
    {
        if (!$this->settings->showsAiLabel()) {
            return '';
        }

        return $this->transparency->provenanceLabel($provenance, $locale);
    }
}
